typedef struct Obj Obj;
typedef void (*Method)(Obj* self);

// V-Table Definition
typedef struct {
    Method execute;
} VTable;

// Base Object Structure (V-pointer mandatory)
struct Obj {
    const VTable* vptr;
};

// Concrete Implementations
void impl_type_a(Obj* o) { /* ... */ }
void impl_type_b(Obj* o) { /* ... */ }

// V-Table Initialization (The "overloads")
const VTable VT_A = { .execute = impl_type_a };
const VTable VT_B = { .execute = impl_type_b };

// Dispatch mechanism (Simulating method call)
#define DISPATCH(obj_ptr) ((obj_ptr)->vptr->execute(obj_ptr))

// Setup Example
Obj obj_instance = { &VT_B };
DISPATCH(&obj_instance);
